Stack LIFO hota hai — Last In First Out, jaise plates ka dherr. Class se saaf implementation:

```python
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if self.is_empty():
            return "Stack khaali hai"
        return self.items.pop()

    def peek(self):
        if self.is_empty():
            return "Stack khaali hai"
        return self.items[-1]

    def is_empty(self):
        return len(self.items) == 0

    def size(self):
        return len(self.items)

s = Stack()
s.push(10)
s.push(20)
s.push(30)
print(s.peek())   # 30 (upar wala, hata nahi)
print(s.pop())    # 30
print(s.pop())    # 20
print(s.size())   # 1
```

push = append, pop = aakhri element nikalna, peek = sirf upar wala dekhna. Teeno O(1) time lete hain.

Har opening bracket ko stack me daalo, closing aaye to upar wale se match karo:

```python
def balanced(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack.pop() != pairs[ch]:
                return False
    return len(stack) == 0

print(balanced("{[()]}"))   # True
print(balanced("{[(])}"))   # False
print(balanced("((a+b)"))   # False
```

Aakhir me stack khaali hona chahiye — bacha matlab koi bracket band hi nahi hua. Ye interview ka mashhoor sawal hai.

Number mile to stack me daalo, operator mile to do number nikaal kar hisaab lagao:

```python
def solve_postfix(expr):
    stack = []
    for token in expr.split():
        if token in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if token == "+": stack.append(a + b)
            elif token == "-": stack.append(a - b)
            elif token == "*": stack.append(a * b)
            else: stack.append(a / b)
        else:
            stack.append(int(token))
    return stack.pop()

print(solve_postfix("5 3 +"))       # 8
print(solve_postfix("4 2 * 6 +"))   # 14
```

Dhyan do: pehle pop hua number 'b' hota hai, dusra 'a' — minus aur bhaag me order ulta hua to jawab galat hoga.

Agar kisi bracket pair ke andar seedha dusra pair aa jaye aur beech me kuch na ho, to wo duplicate hai:

```python
def has_duplicate(expr):
    stack = []
    for ch in expr:
        if ch == ")":
            count = 0
            while stack and stack[-1] != "(":
                stack.pop()
                count += 1
            if stack:
                stack.pop()  # '(' hatao
            if count == 0:
                return True  # () ke andar kuch nahi tha
        else:
            stack.append(ch)
    return False

print(has_duplicate("((a+b))"))     # True
print(has_duplicate("(a+(b+c))"))   # False
```

count == 0 matlab band bracket ke theek peeche khulta bracket tha — beech me koi content nahi, wahi duplicate ki nishaani hai.

Ek extra 'min stack' rakho — har push ke saath ab tak ka sabse chhota bhi save karo:

```python
class MinStack:
    def __init__(self):
        self.stack = []
        self.mins = []

    def push(self, x):
        self.stack.append(x)
        if not self.mins or x <= self.mins[-1]:
            self.mins.append(x)

    def pop(self):
        x = self.stack.pop()
        if x == self.mins[-1]:
            self.mins.pop()
        return x

    def get_min(self):
        return self.mins[-1]

m = MinStack()
for n in [5, 3, 7, 2, 8]:
    m.push(n)
print(m.get_min())   # 2
m.pop(); m.pop()
print(m.get_min())   # 3
```

Har baar puri list scan karne ki jagah mins ka upar wala hi jawab hai — pop par bhi min apne aap sahi rehta hai.

Delete karne ke liye usse pichhle node ka next, agle node par laga do:

```python
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        new = Node(data)
        if not self.head:
            self.head = new
            return
        cur = self.head
        while cur.next:
            cur = cur.next
        cur.next = new

    def delete(self, value):
        if self.head and self.head.data == value:
            self.head = self.head.next
            return
        cur = self.head
        while cur and cur.next:
            if cur.next.data == value:
                cur.next = cur.next.next
                return
            cur = cur.next

    def show(self):
        cur = self.head
        out = []
        while cur:
            out.append(str(cur.data))
            cur = cur.next
        return " -> ".join(out)

ll = LinkedList()
for n in [5, 10, 15, 20]:
    ll.append(n)
ll.delete(15)
print(ll.show())   # 5 -> 10 -> 20
ll.delete(5)
print(ll.show())   # 10 -> 20
```

Head delete hona alag case hai (head hi badal jata hai) — yahi galti sabse zyada hoti hai, isiliye use pehle sambhala.

