class ATM:
    def __init__(self, pin, balance):
        self.pin = pin
        self.balance = balance
        self.tries = 0

    def enter_pin(self, pin):
        if self.tries >= 3:
            return "Card block ho gaya hai"
        if pin == self.pin:
            self.tries = 0
            return "PIN sahi hai, swagat hai"
        self.tries += 1
        return "Galat PIN! Mauke bache: " + str(3 - self.tries)

