Har kitab ki haalat (available/issued) uske saath rehti hai:

```python
class Book:
    def __init__(self, title, author):
        self.title = title
        self.author = author
        self.issued_to = None

class Library:
    def __init__(self):
        self.books = []

    def add_book(self, title, author):
        self.books.append(Book(title, author))

    def issue(self, title, student):
        for b in self.books:
            if b.title == title and b.issued_to is None:
                b.issued_to = student
                return title + " mil gayi " + student + " ko"
        return "Kitab uplabdh nahi hai"

    def give_back(self, title):
        for b in self.books:
            if b.title == title and b.issued_to is not None:
                b.issued_to = None
                return title + " wapas aa gayi"
        return "Ye kitab issued hi nahi thi"

lib = Library()
lib.add_book("Python Seekho", "Sharma")
lib.add_book("Bharat ka Itihaas", "Gupta")
print(lib.issue("Python Seekho", "Rahul"))
print(lib.issue("Python Seekho", "Priya"))   # uplabdh nahi
print(lib.give_back("Python Seekho"))
print(lib.issue("Python Seekho", "Priya"))   # ab mil gayi
```

