Kamre ek dict me: number -> mehman ka naam (None matlab khaali):

```python
class Hotel:
    def __init__(self, rooms):
        self.rooms = {r: None for r in rooms}

    def book(self, guest):
        for room, g in self.rooms.items():
            if g is None:
                self.rooms[room] = guest
                return "Kamra " + str(room) + " mila " + guest + " ko"
        return "Koi kamra khaali nahi hai"

    def checkout(self, room):
        guest = self.rooms.get(room)
        if guest:
            self.rooms[room] = None
            return guest + " ne kamra " + str(room) + " chhod diya"
        return "Ye kamra khaali hi tha"

    def khaali(self):
        return [r for r, g in self.rooms.items() if g is None]

h = Hotel([101, 102, 103])
print(h.book("Rahul"))     # Kamra 101
print(h.book("Priya"))     # Kamra 102
print(h.khaali())          # [103]
print(h.checkout(101))     # Rahul ne chhod diya
print(h.khaali())          # [101, 103]
```

Pehla khaali kamra milte hi book — dict ka kram yahan dost ban jata hai kyunki Python dict purana kram yaad rakhta hai.

