class Inventory:
    def __init__(self):
        self.stock = {}

    def add(self, item, qty):
        self.stock[item] = self.stock.get(item, 0) + qty

    def sell(self, item, qty):
        if self.stock.get(item, 0) < qty:
            return "Stock kam hai: " + item
        self.stock[item] -= qty
        return "Bik gaya: " + item + " x" + str(qty)

