                return name + " ko bed " + str(bed) + " mila"
        return "Koi bed khaali nahi"

    def discharge(self, name):
        for bed, p in self.beds.items():
            if p == name:
                self.beds[bed] = None
                return name + " discharge ho gaye (bed " + str(bed) + ")"
        return "Ye mareez yahan nahi hai"

h = Hospital(2)
print(h.admit("Mohan", "Bukhaar"))   # bed 1
print(h.admit("Sita", "Pet dard"))   # bed 2
print(h.admit("Ram", "Chot"))        # Koi bed khaali nahi
print(h.discharge("Mohan"))          # bed 1 khaali
print(h.admit("Ram", "Chot"))        # ab bed 1 mil gaya
```

Hotel wale hi dhanche par hai — bed ya kamra, niyam ek: khaali dhundho, bharo, khaali karo.

