Koshish gin kar lock lagana hi asal suraksha ki shuruaat hai:

```python
class LoginSystem:
    def __init__(self):
        self.users = {}
        self.attempts = {}
        self.locked = set()

    def register(self, user, password):
        if user in self.users:
            return "Ye naam pehle se hai"
        self.users[user] = password
        return "Khata ban gaya"

    def login(self, user, password):
        if user in self.locked:
            return "Khata LOCK hai — zyada galat koshish"
        if self.users.get(user) == password:
            self.attempts[user] = 0
            return "Swagat hai, " + user
        self.attempts[user] = self.attempts.get(user, 0) + 1
        if self.attempts[user] >= 3:
            self.locked.add(user)
            return "3 galat koshish — khata LOCK ho gaya"
        return "Galat password, koshish: " + str(self.attempts[user])

s = LoginSystem()
print(s.register("vishesh", "pass123"))
