```python
class TicTacToe:
    LINES = [(0,1,2),(3,4,5),(6,7,8),
             (0,3,6),(1,4,7),(2,5,8),
             (0,4,8),(2,4,6)]

    def __init__(self):
        self.board = [" "] * 9

    def move(self, pos, mark):
        if self.board[pos] != " ":
            return "Ye dabba bhara hai"
        self.board[pos] = mark
        return self.winner() or "Chaal chal gayi"

    def winner(self):
        for a, b, c in self.LINES:
            if self.board[a] != " " and self.board[a] == self.board[b] == self.board[c]:
                return self.board[a] + " jeet gaya!"
        if " " not in self.board:
            return "Draw ho gaya"
        return None

    def show(self):
        for i in range(0, 9, 3):
            print(" | ".join(self.board[i:i+3]))

g = TicTacToe()
g.move(0, "X"); g.move(3, "O"); g.move(1, "X"); g.move(4, "O")
print(g.move(2, "X"))   # X jeet gaya!
g.show()
```

