Shabd ke akshar chhupe, sahi guess par khulte hain, galat par jaan kam:

```python
class Hangman:
    def __init__(self, word, lives=6):
        self.word = word
        self.lives = lives
        self.guessed = set()

    def guess(self, ch):
        self.guessed.add(ch)
        if ch not in self.word:
            self.lives -= 1
            return "Galat! Jaan bachi: " + str(self.lives)
        return "Sahi!"

    def display(self):
        return " ".join(ch if ch in self.guessed else "_" for ch in self.word)

    def won(self):
        return all(ch in self.guessed for ch in self.word)

    def over(self):
        return self.won() or self.lives <= 0

h = Hangman("pani")
print(h.display())      # _ _ _ _
print(h.guess("a"))     # Sahi!
print(h.display())      # _ a _ _
print(h.guess("x"))     # Galat! Jaan bachi: 5
h.guess("p"); h.guess("n"); h.guess("i")
print(h.won())          # True
```

