class QueueFromStacks:
    def __init__(self):
        self.inbox = []
        self.outbox = []

    def enqueue(self, x):
        self.inbox.append(x)

    def dequeue(self):
        if not self.outbox:
            while self.inbox:
                self.outbox.append(self.inbox.pop())
        if not self.outbox:
            return "Khaali hai"
        return self.outbox.pop()

q = QueueFromStacks()
q.enqueue(1); q.enqueue(2); q.enqueue(3)
print(q.dequeue())   # 1
q.enqueue(4)
print(q.dequeue())   # 2
print(q.dequeue())   # 3
print(q.dequeue())   # 4
