Do binary search: ek bayein dabata hua, ek dayein:

```python
def first_last(arr, target):
    def search(left_most):
        low, high = 0, len(arr) - 1
        pos = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == target:
                pos = mid
                if left_most:
                    high = mid - 1
                else:
                    low = mid + 1
            elif arr[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return pos
    return search(True), search(False)

print(first_last([5, 7, 7, 8, 8, 10], 8))   # (3, 4)
print(first_last([5, 7, 7, 8, 8, 10], 6))   # (-1, -1)
```

