#include <stdio.h>

int main() {
    int a = 7, b = 3, c = 12;
    if (a >= b && a >= c)
        printf("Sabse bada: %d", a);
    else if (b >= a && b >= c)
        printf("Sabse bada: %d", b);
    else
        printf("Sabse bada: %d", c);
    return 0;
}
```

Output: `Sabse bada: 12`

- Pehle a ko dono se bada check kiya (`&&` matlab dono shartein sahi)
- Phir b ko, warna aakhir wala c khud hi sabse bada hoga

