Pyramid aur uska ulta jod do:

```c
#include <stdio.h>

int main() {
    int i, j;
    for (i = 1; i <= 3; i++) {              // upar wala hissa
        for (j = 1; j <= 3 - i; j++) printf(" ");
        for (j = 1; j <= 2 * i - 1; j++) printf("*");
        printf("\n");
    }
    for (i = 2; i >= 1; i--) {              // neeche wala (ulta)
        for (j = 1; j <= 3 - i; j++) printf(" ");
        for (j = 1; j <= 2 * i - 1; j++) printf("*");
        printf("\n");
    }
    return 0;
}
```

Output:
```
  *
