<input id="naam"><p id="naamErr" style="color:red"></p>
```
```javascript
function checkNaam() {
  let v = document.getElementById('naam').value;
  document.getElementById('naamErr').textContent =
    v.trim().length < 3 ? 'Naam bahut chhota hai' : '';
}
```

Dabbe par `oninput="checkNaam()"` lagao — likhte-likhte hi galti dikhegi aur sahi hote hi gayab. Ek bada sandesh upar rakhne se ye tareeka behtar hai kyunki user ko turant pata chalta hai galti kahan hai.

Sawal ek saaf format me rakho — har sawal ek object:

```javascript
let sawal = [
  { q: '2 + 3 kitna hota hai?', o: ['Option A', 'Option B', 'Option C', 'Option D'], a: 0 },
  { q: 'Apna dusra sawal yahan', o: ['A', 'B', 'C', 'D'], a: 2 }
];
```

`a` hamesha sahi option ka **number** hai aur ginati 0 se shuru hoti hai (pehla option = 0). maths ke sawal isiliye array me rakhte hain taaki sawal badalna ya badhana bina code chhede ho — data alag, chalane wala code alag.

Ek input, ek formula (1 minute = 60 second):

```javascript
function badlo() {
  let v = parseFloat(document.getElementById('n').value);
  if (isNaN(v)) { alert('Number dalo'); return; }
  document.getElementById('out').textContent = 'Jawab: ' + (v * 60);
}
```

Saare converter ek hi dhache ke hain — input lo, jaancho, formula lagao, dikhao. Formula badlo, naya tool taiyaar. Jawab me ikai (unit) ka naam bhi likh do to user ko aur saaf samajh ayega.

Aksharo ke dabbe se beech-beech ke akshar uthao:

```javascript
function banao() {
  let akshar = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#%&';
  let pw = '';
  for (let i = 0; i < 10; i++) {
    pw += akshar[Math.floor(Math.random() * akshar.length)];
  }
  document.getElementById('out').textContent = pw;
}
```

`Math.random() * akshar.length` dabbe ke andar ka koi bhi number deta hai, `Math.floor` use pura number banata hai. 10 ki jagah lambai badha sakte ho — lamba password zyada majboot hota hai.

Aakhri dot ke baad wala hissa:

```javascript
function ext(naam) {
  return naam.slice(naam.lastIndexOf('.') + 1).toLowerCase();
}
console.log(ext('Meri Photo.JPG'));   // jpg
```

`lastIndexOf` aakhri dot deta hai (naam me pehle bhi dot ho sakta hai — 'meri.file.jpg'). Dot na ho to lastIndexOf -1 dega aur slice(0) pura naam de dega — pehle `includes('.')` check kar lena behtar.

Input par `min` lagana sabse saaf hal hai:

```javascript
let aaj = new Date();
let text = aaj.getFullYear() + '-' + String(aaj.getMonth() + 1).padStart(2, '0') + '-' + String(aaj.getDate()).padStart(2, '0');
document.getElementById('tar').min = text;
```

Date input ka format hamesha `YYYY-MM-DD` hota hai — isliye text haath se jodna pada. `min` lagte hi calender me purani tareekh band ho jati hai, JS ki jaanch ki bhi zaroorat nahi.

```javascript
let vakya = 'mujhe coding seekhni hai';
let hisse = vakya.split(' ');
console.log(hisse);
console.log('Kul hisse:', hisse.length);
```

`split` jis nishan ko doge wahi se katega — space, comma, dash. Ulta (list se text) `join` hai. Naam ginana, tag todna, CSV padhna — sab split par chalta hai.

To-do list ka pura code — add, delete aur list dikhana:

```html
<input id="inp" placeholder="task likho...">
<button onclick="jodo()">Add</button>
<ul id="list"></ul>
<script>
function jodo() {
  let v = document.getElementById('inp').value;
  if (v === '') return;
  let li = document.createElement('li');
  li.innerHTML = v + ' <button onclick="this.parentElement.remove()">X</button>';
  document.getElementById('list').appendChild(li);
  document.getElementById('inp').value = '';
}
</script>
```

Samjho: `createElement('li')` se naya task banta hai, `appendChild` se list me judta hai, aur har task ke saath apna delete button hai jo `this.parentElement.remove()` se poora task hata deta hai. Khali input par `return` se kuch add nahi hota.

Counter + localStorage — band karke kholo, ginati wahi:

```javascript
let n = parseInt(localStorage.getItem('jaap') || '0');
document.getElementById('num').textContent = n;
function badlo() {
  n++;
  document.getElementById('num').textContent = n;
  localStorage.setItem('jaap', n);
}
function reset() { n = 0; document.getElementById('num').textContent = 0; localStorage.setItem('jaap', 0); }
```

`parseInt` text ko number banata hai — localStorage hamesha text rakhta hai, ye baat bhoolna sabse aam galti hai (warna 5 + 1 = 51 ho jayega, kyunki text jud jayega).

`split` aur `length` ka khel:

```javascript
document.getElementById('txt').addEventListener('input', function() {
  let t = this.value;
  let akshar = t.length;
  let shabd = t.trim() === '' ? 0 : t.trim().split(/\s+/).length;
  document.getElementById('gin').textContent = 'Akshar: ' + akshar + ' | Shabd: ' + shabd;
});
```

Shabd ginane ki chaabi: `trim()` aage-peeche ki khali jagah saaf kare, `split(/\s+/)` ek ya zyada space par kaate. Khali dabbe par 0 dikhana na bhoolo — warna ''.split se 1 shabd gin liya jayega.

```javascript
let naam = ['Ravi', 'Seema', 'Aman'];
naam.splice(1, 1);              // 1 number se 1 item hataya
console.log(naam);
naam.splice(1, 0, 'Priya');      // 1 number par bina hataye joda
console.log(naam);
```

`splice(shuru, kitneHataye, ...jodnaHai)` — teen kaam ek me: hatana, jodna, badalna (hatakar jodna). Ye asal list ko badalta hai, isliye hosh se use karo.

Ek toggle aur bahar click par band:

```javascript
function menuBadlo() {
  document.getElementById('menu').classList.toggle('khula');
}
document.addEventListener('click', function(e) {
  if (!e.target.closest('#menuDabba')) {
    document.getElementById('menu').classList.remove('khula');
  }
});
```

```css
#menu { display: none; }
#menu.khula { display: block; }
```

`closest` batata hai click menu ke dabbe ke andar hua ya bahar. Bahar click par band hona har achhe menu ki pehchan hai — warna menu khula hi reh jata hai.

Har shart ki alag jaanch, sandesh bhi alag:

```javascript
function pwCheck() {
  let v = document.getElementById('pw').value;
  if (v.length < 8) return 'Kam se kam 8 akshar';
  if (!/[0-9]/.test(v)) return 'Ek number zaroor dalo';
  if (!/[A-Z]/.test(v)) return 'Ek bada akshar (A-Z) dalo';
  return 'Password majboot hai';
}
```

Ek bada regex likhne ki jagah alag-alag jaanch user ko batati hai **kya** kam hai. Bhejne se pehle aur likhte-likhte — dono jagah ye function chal sakta hai.

Farak ko tod-tod kar dikhao:

```javascript
let nishaana = new Date('2027-01-01T00:00:00');
setInterval(function() {
  let farak = nishaana - new Date();
  let din = Math.floor(farak / 86400000);
  let gh = Math.floor(farak / 3600000) % 24;
  let min = Math.floor(farak / 60000) % 60;
  document.getElementById('cd').textContent = din + ' din ' + gh + ' ghante ' + min + ' minute bache';
}, 1000);
```

Millisecond ke hisaab rat lo: din = 86400000, ghanta = 3600000, minute = 60000. `% 24` aur `% 60` bacha hua hissa dete hain warna ghante 50+ dikhenge.

File ke naam ke aakhir se pehchan:

```javascript
function fileCheck() {
  let f = document.getElementById('file').files[0];
  if (!f) return;
  let naam = f.name.toLowerCase();
  if (!naam.endsWith('.jpg') && !naam.endsWith('.png')) {
    alert('Sirf JPG ya PNG photo chuno');
    document.getElementById('file').value = '';
  }
}
```

`files[0]` pehli chuni file deta hai. HTML me `accept=".jpg,.png"` bhi laga sakte ho — chunne ke samay hi dusri file dikhegi hi nahi. Dono bandobast ek saath sabse pakke.

Event ki tafseel hi tool hai:

```javascript
document.addEventListener('keydown', function(e) {
  document.getElementById('out').textContent =
    'Dabi: ' + e.key + ' | Code: ' + e.code;
});
```

`e.key` akshar deta hai ('a', 'Enter', ' '), `e.code` keyboard par jagah ('KeyA', 'Space'). Game banane me code kaam aata hai, form me key. Kheli gayi key se page ghumne (scroll) se rokna ho to `e.preventDefault()`.

Sawal aate hi ulta timer, samay khatam to khud agla sawal:

```javascript
let bache, timer;
function dikhao() {
  // ... sawal dikhane ka code ...
  bache = 10;
  document.getElementById('t').textContent = bache;
  clearInterval(timer);
  timer = setInterval(function() {
    bache--;
    document.getElementById('t').textContent = bache;
    if (bache <= 0) { clearInterval(timer); ab++; ab < sawal.length ? dikhao() : khatam(); }
  }, 1000);
}
```

Sabse zaroori line `clearInterval(timer)` hai — naya sawal aane par purana timer band karo, warna do timer ek saath chalenge aur ginati ajeeb bhagegi.

Ek loop, do dabbe:

```javascript
let jor = '', visham = '';
for (let i = 1; i <= 100; i++) {
  if (i % 2 === 0) jor += i + ' ';
  else visham += i + ' ';
}
document.getElementById('jor').textContent = jor;
document.getElementById('visham').textContent = visham;
```

`i % 2 === 0` jor (even) ki pehchan hai — 2 se bhaag par bacha 0. Yahi soch 3 se katne wale, 5 se katne wale — har chhantni (filter) par chalti hai.

Input par `keydown` event lagao aur Enter (key === 'Enter') check karo:

```javascript
document.getElementById('inp').addEventListener('keydown', function(e) {
  if (e.key === 'Enter') jodo();
});
```

`e.key` batata hai kaunsi key dabi. Enter par wahi `jodo()` function chalega jo button par chalta hai — do jagah ek hi kaam, isliye function alag bana kar rakha jata hai.

