Shreni ke kul se sabse bada chunna:

```javascript
let kul = {};
hisaab.forEach(function(h) {
  if (h.prakar === 'gaya') kul[h.shr] = (kul[h.shr] || 0) + h.rakam;
});
let badi = Object.keys(kul).reduce(function(a, b) { return kul[a] > kul[b] ? a : b; });
console.log('Sabse zyada kharcha:', badi, '—', kul[badi], 'rupaye');
