Har badlav par puri list ko localStorage me save karo aur shuru me wahi se load karo:

```javascript
let kaam = JSON.parse(localStorage.getItem('kaam') || '[]');
function save() { localStorage.setItem('kaam', JSON.stringify(kaam)); }
function dikhao() {
  document.getElementById('list').innerHTML =
    kaam.map((k, i) => '<li>' + k + ' <button onclick="hatao(' + i + ')">X</button></li>').join('');
