  let d = new Date();
  let utc = d.getTime() + d.getTimezoneOffset() * 60000;
  let dusra = new Date(utc + offset * 3600000);
  return dusra.getHours() + ':' + String(dusra.getMinutes()).padStart(2, '0');
}
console.log('London:', dusraSamay(0), ' Dubai:', dusraSamay(4));
