function jodo() {
  let v = document.getElementById('txt').value;
  if (v === '') return;
  notes.push(v); save(); dikhao();
  document.getElementById('txt').value = '';
}
function hatao(i) { notes.splice(i, 1); save(); dikhao(); }
dikhao();
```

Dhacha to-do list wala hi hai — farak bas itna ki yahan lamba text (textarea) hota hai. Ek baar ye pattern samajh aaya to notes, kharcha, contact — sab apps ban jayenge.

