Har dabbe par `input` event, bhara to agle par focus:

```html
<input maxlength="1" class="otp"><input maxlength="1" class="otp">
<input maxlength="1" class="otp"><input maxlength="1" class="otp">
<script>
let dabbe = document.querySelectorAll('.otp');
dabbe.forEach(function(d, i) {
  d.addEventListener('input', function() {
    if (d.value !== '' && i < 3) dabbe[i + 1].focus();
